package com.yskj.shopify.web.service;
import com.alibaba.fastjson.*;import com.yskj.dao.dto.org.LoginedUser;import com.yskj.shopify.contract.connection.ICustomStoreConnectionService;import java.lang.reflect.*;import java.util.*;import java.util.concurrent.atomic.AtomicReference;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.*;
class CustomStoreAutomationReadonlyTest {
 JSONObject view(){var v=new JSONObject();v.put("schemaVersion",1);v.put("shopDomain","custom.example");v.put("available",true);v.put("featureEnabled",true);v.put("canManage",true);v.put("configVersion",3);v.put("automationVersion",1);v.put("pollEnabled",true);v.put("callbackEnabled",true);v.put("pollIntervalSeconds",300);v.put("baselineReady",true);v.put("awaitingBaseline",false);v.put("hasPendingCallback",false);v.put("environment","TEST");v.put("effectPolicy","SUPPRESS");return v;}
 JSONObject read(JSONObject raw,AtomicReference<JSONObject> captured,String method){var remote=(ICustomStoreConnectionService)Proxy.newProxyInstance(getClass().getClassLoader(),new Class<?>[]{ICustomStoreConnectionService.class},(p,m,a)->{if(a!=null&&a.length==1)captured.set((JSONObject)a[0]);return raw;});var c=new CustomStoreConnectionClient(remote);var u=new LoginedUser();u.setId("member");u.setDomainid("tenant");try{return (JSONObject)c.getClass().getMethod(method,LoginedUser.class,String.class).invoke(c,u,"custom.example");}catch(NoSuchMethodException missing){throw new AssertionError("readonly automation model not implemented",missing);}catch(ReflectiveOperationException rejected){throw new AssertionError(rejected);}}
 @Test void merchantAutomationIsReadOnlyEvenForPrivilegedRawReply(){var raw=view();raw.put("signingSecret","private-secret");raw.put("callbackUrl","https://hooks.example/callbacks/auw/v2/11111111-1111-4111-8111-111111111111");var captured=new AtomicReference<JSONObject>();var v=read(raw,captured,"automationStatus");assertThat(v.getBooleanValue("available")).isTrue();assertThat(v.getBooleanValue("canManage")).isFalse();assertThat(v.toJSONString()).doesNotContain("private-secret","signingSecret");assertThat(captured.get().getString("surface")).isEqualTo("MERCHANT");}
 @Test void merchantIdentityViewExcludesNamesIdsAndOriginalEmail(){var raw=view();raw.remove("automationVersion");var row=new JSONObject();row.put("sourceCustomerId","native-private");row.put("importedContactId","import-private");row.put("sourceName","private-name");row.put("importedName","private-name");row.put("maskedEmail","a***@example.test");row.put("email","private-email@example.test");row.put("identityVersion",1);row.put("linked",true);raw.put("candidates",new JSONArray(List.of(row)));var v=read(raw,new AtomicReference<>(),"identityStatus");assertThat(v.getBooleanValue("canManage")).isFalse();assertThat(v.toJSONString()).doesNotContain("private","sourceCustomerId","importedContactId","sourceName","importedName","email");assertThat(v.getIntValue("linkedOnPage")).isEqualTo(1);}
 @Test void malformedAndOldCoreRepliesDoNotEnableControls(){var raw=view();raw.put("pollEnabled","true");assertThat(read(raw,new AtomicReference<>(),"automationStatus").getBooleanValue("available")).isFalse();assertThat(read(null,new AtomicReference<>(),"automationStatus").getBooleanValue("available")).isFalse();}
}
